  <main id="main">
    <section class="hero" id="top" aria-labelledby="hero-title">
      <div class="hero-copy">
        <p class="eyebrow"><span class="blue-dot"></span> MADE FOR THE EVERYDAY</p>
        <h1 id="hero-title">Find your fit.<br><span>Keep your pace.</span></h1>
        <p class="hero-intro">No noise. No guesswork. Just denim that feels like yours from day one.</p>
        <a class="button button-blue" href="#shop">Shop denim <span aria-hidden="true">↗</span></a>
        <p class="hero-note">01 / EVERYDAY DENIM COLLECTION</p>
      </div>
      <figure class="hero-image">
        <img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" data-inline-image="hero" alt="An everyday denim look against sunlit, minimal city architecture" width="1536" height="1024" fetchpriority="high">
        <figcaption><span>THE EVERYDAY EDIT</span><span>ISSUE 01 — DENIM</span></figcaption>
        <div class="image-stamp" aria-hidden="true">GOOD<br>DENIM<br>ONLY<span>✳</span></div>
      </figure>
      <a class="hero-side-link" href="#shop">SCROLL TO YOUR NEXT FAVORITE <span aria-hidden="true">↓</span></a>
    </section>

    <section class="ticker" aria-label="Brand values"><div>GOOD FIT. GOOD FABRIC. <span>✳</span> NOTHING EXTRA. <span>✳</span> GOOD FIT. GOOD FABRIC. <span>✳</span> NOTHING EXTRA. <span>✳</span></div></section>

    <section class="collection section-wrap" id="shop" aria-labelledby="shop-title">
      <div class="section-heading">
