          <button class="product-photo" type="button" data-product="everyday-straight" aria-label="View The Everyday Straight details">
            <img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" data-inline-image="straight" alt="Mid-indigo straight-fit jeans styled with a white tee" width="800" height="1000" loading="lazy">
            <span class="photo-index">01 / STRAIGHT</span><span class="quick-view">VIEW FIT <span aria-hidden="true">↗</span></span>
          </button>
          <div class="product-meta"><div><h3>The Everyday Straight</h3><p>Mid indigo · 100% cotton feel</p></div><span class="price">$68</span></div>
          <button class="text-link add-card" type="button" data-quick-add="everyday-straight">Quick add <span aria-hidden="true">+</span></button>
        </article>
        <article class="product-card" data-id="wide-open" data-fit="wide" data-price="72" data-index="1">
          <button class="product-photo" type="button" data-product="wide-open" aria-label="View The Wide Open details">
            <img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" data-inline-image="wide" alt="Dark-indigo high-rise wide-leg jeans with a clean silhouette" width="800" height="1000" loading="lazy">
            <span class="photo-index">02 / WIDE LEG</span><span class="quick-view">VIEW FIT <span aria-hidden="true">↗</span></span>
          </button>
          <div class="product-meta"><div><h3>The Wide Open</h3><p>Deep indigo · High rise</p></div><span class="price">$72</span></div>
          <button class="text-link add-card" type="button" data-quick-add="wide-open">Quick add <span aria-hidden="true">+</span></button>
        </article>
        <article class="product-card" data-id="easy-taper" data-fit="relaxed" data-price="68" data-index="2">
          <button class="product-photo" type="button" data-product="easy-taper" aria-label="View The Easy Taper details">
            <img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" data-inline-image="relaxed" alt="Light vintage-wash relaxed tapered denim jeans" width="800" height="1000" loading="lazy">
            <span class="photo-index">03 / RELAXED</span><span class="quick-view">VIEW FIT <span aria-hidden="true">↗</span></span>
          </button>
          <div class="product-meta"><div><h3>The Easy Taper</h3><p>Vintage wash · Relaxed fit</p></div><span class="price">$68</span></div>
          <button class="text-link add-card" type="button" data-quick-add="easy-taper">Quick add <span aria-hidden="true">+</span></button>
        </article>
      </div>
      <p class="empty-state" id="empty-state" hidden>No fits in this edit yet. Try another filter.</p>
    </section>

    <section class="story section-wrap" id="story" aria-labelledby="story-title">
      <div class="story-image"><img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" data-inline-image="detail" alt="Close-up of denim weave, copper hardware and careful stitching" width="800" height="1000" loading="lazy"><span>DETAIL NO. 01 — THE GOOD STUFF</span></div>
      <div class="story-copy"><p class="eyebrow">LESS CHASING, MORE WEARING</p><h2 id="story-title">A good pair<br>makes the day<span class="blue-period">.</span></h2><p>We believe finding your jeans should feel easy. So we keep the lineup focused, the fit notes clear, and the denim ready to go where you do.</p><a class="underlined-link" href="#shop">Meet your new pair <span aria-hidden="true">↗</span></a><span class="story-mark" aria-hidden="true">gyd<br>///</span></div>
    </section>

    <section class="promise-band" aria-label="Store promise"><div><span class="eyebrow">CLEAR FIT NOTES</span><strong>Know what<br>you’re getting.</strong></div><span class="promise-cross" aria-hidden="true">✳</span><div><span class="eyebrow">THREE GO-TO FITS</span><strong>Easy to choose.<br>Easy to wear.</strong></div><span class="promise-cross" aria-hidden="true">✳</span><div><span class="eyebrow">BUILT FOR YOUR ROUTINE</span><strong>Less fuss.<br>More favorite.</strong></div></section>

    <section class="info-section section-wrap" id="shipping" aria-labelledby="shipping-title">
      <div class="info-heading"><p class="eyebrow">THE USEFUL DETAILS</p><h2 id="shipping-title">Before you<br>make it yours<span class="blue-period">.</span></h2><p>Simple answers, no small-print treasure hunt. The details here are sample store policies and should be reviewed before real orders are accepted.</p></div>
      <div class="policy-list">
        <details open><summary><span>01</span> Shipping <b aria-hidden="true">+</b></summary><div class="policy-copy"><p>Sample shipping policy: allow 1–3 business days for processing and 3–7 business days for standard US delivery. Example rates: $6.95 standard shipping, complimentary standard shipping on sample orders over $100. These sample rates and delivery windows are not live carrier quotes.</p></div></details>
        <details id="returns"><summary><span>02</span> Returns &amp; exchanges <b aria-hidden="true">+</b></summary><div class="policy-copy"><p>Sample return policy: request a return within 30 days of delivery. Items should be unworn, unwashed and have original tags attached. A return shipping label and any applicable return costs must be confirmed by the store before launch. Sale-item exclusions and exchange availability need owner review.</p></div></details>
        <details id="terms"><summary><span>03</span> Terms &amp; conditions <b aria-hidden="true">+</b></summary><div class="policy-copy"><p>This demo storefront is for browsing only. Product descriptions, example prices, availability, delivery promises and policies may change and are not a binding offer. A real launch needs owner-approved terms, governing-law information, order acceptance rules, tax handling and actual fulfilment procedures. Nothing is purchased or submitted through this demo.</p></div></details>
        <details id="privacy"><summary><span>04</span> Privacy <b aria-hidden="true">+</b></summary><div class="policy-copy"><p>This demo does not send orders or customer information to a server. Your bag is stored in this browser only. Do not enter personal or payment information. A live shop must publish an owner-reviewed privacy notice describing its actual data use, processors, retention and customer rights.</p></div></details>
      </div>
    </section>

    <section class="contact-section" id="contact" aria-labelledby="contact-title">
      <div class="contact-top"><p class="eyebrow">GOOD QUESTION? SAY HELLO.</p><span class="contact-number">05 — CONTACT</span></div>
      <h2 id="contact-title">We’re easy<br>to reach<span class="contact-blue">.</span></h2>
      <a class="contact-email" href="mailto:getyourdenim@gmail.com">getyourdenim@gmail.com <span aria-hidden="true">↗</span></a>
      <div class="store-address"><span class="eyebrow">USA STORE ADDRESS · SAMPLE</span><address>getyourdenim<br>123 Denim Lane<br>Brooklyn, NY 11211<br>United States</address><p>This is a sample address, not a verified store location. Replace it with your real business address before publishing for customers.</p></div>
    </section>
  </main>

  <footer class="site-footer"><a class="footer-wordmark" href="#top">getyourdenim<span>.</span></a><p>Good denim. No detours.</p><nav aria-label="Footer links"><a href="#terms">Terms &amp; conditions</a><a href="#returns">Returns</a><a href="#shipping">Shipping</a><a href="#privacy">Privacy</a><a href="mailto:getyourdenim@gmail.com">Email us</a></nav><small>© <span id="year">2026</span> getyourdenim. Sample storefront — review all store details before launch.</small></footer>

  <dialog class="product-dialog" id="product-dialog" aria-labelledby="dialog-product-title"><button class="dialog-close" type="button" data-close-dialog aria-label="Close product details">×</button><div class="detail-image"><img id="detail-image" src="" alt="" width="800" height="1000"></div><div class="detail-content"><p class="eyebrow" id="detail-fit">DENIM / FIT</p><h2 id="dialog-product-title"></h2><p class="detail-price" id="detail-price"></p><p id="detail-description" class="detail-description"></p><fieldset class="size-fieldset"><legend>Choose waist size <span>US sizing</span></legend><div class="size-options" id="size-options"></div></fieldset><p class="size-hint">Not sure? Check the fit note above, or email us.</p><button class="button button-blue detail-add" id="detail-add" type="button">Add to bag <span aria-hidden="true">↗</span></button></div></dialog>

  <dialog class="cart-dialog" id="cart-dialog" aria-labelledby="cart-title"><div class="cart-header"><div><p class="eyebrow">YOUR PICKS</p><h2 id="cart-title">Your bag<span class="blue-period">.</span></h2></div><button class="dialog-close" type="button" data-close-dialog aria-label="Close shopping bag">×</button></div><div class="cart-items" id="cart-items"></div><div class="cart-empty" id="cart-empty"><span class="cart-empty-mark" aria-hidden="true">gyd</span><p>Your bag is taking a breather.</p><a href="#shop" class="underlined-link" data-close-dialog>Find your fit <span aria-hidden="true">↗</span></a></div><div class="cart-footer" id="cart-footer"><div class="subtotal"><span>Subtotal</span><strong id="cart-subtotal">$0.00</strong></div><p class="demo-disclaimer">This demo does not take payment or send an order. Shipping and taxes are not calculated.</p><button class="button button-blue checkout-button" id="checkout-button" type="button">Continue to demo checkout <span aria-hidden="true">↗</span></button><p class="cart-email">Questions? <a href="mailto:getyourdenim@gmail.com">getyourdenim@gmail.com</a></p></div><div class="checkout-complete" id="checkout-complete" hidden><span class="checkout-check" aria-hidden="true">✓</span><h3>Demo order complete.</h3><p>No payment was taken and no order or personal details were sent. Thanks for taking a look.</p><button class="button button-outline" id="finish-demo" type="button">Back to the shop</button></div></dialog>
  <div class="dialog-backdrop" hidden></div>
  <div class="status-message" id="status-message" aria-live="polite" role="status"></div>
  <script type="application/json" id="embedded-media">{"hero":"data:image/webp;base64,","straight":"data:image/webp;base64,","wide":"data:image/webp;base64,","relaxed":"data:image/webp;base64,","detail":"data:image/webp;base64,"}</script>
  <script>
const media = JSON.parse(document.getElementById('embedded-media').textContent);
const products = {
  'everyday-straight': {
    name: 'The Everyday Straight', fit: 'STRAIGHT / MID INDIGO', color: 'Mid indigo', price: 68,
    image: media.straight,
    description: 'An easy straight leg with a mid rise and clean, everyday shape. A versatile denim staple made to feel familiar from the first wear.'
  },
  'wide-open': {
    name: 'The Wide Open', fit: 'WIDE LEG / DEEP INDIGO', color: 'Deep indigo', price: 72,
    image: media.wide,
    description: 'A high-rise waist meets a roomy wide leg. Easy through the hip, relaxed from the knee down, and ready for a little more space.'
  },
  'easy-taper': {
    name: 'The Easy Taper', fit: 'RELAXED / VINTAGE WASH', color: 'Vintage wash', price: 68,
    image: media.relaxed,
    description: 'A comfortable relaxed top block that tapers neatly toward the ankle. Finished in a lived-in pale wash for everyday rotation.'
  }
};
const waistSizes = ['28', '30', '32', '34', '36'];
const storageKey = 'getyourdenim-demo-bag-v1';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const money = (amount) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
const productDialog = $('#product-dialog');
const cartDialog = $('#cart-dialog');
const cartItems = $('#cart-items');
const cartSubtotal = $('#cart-subtotal');
const bagCount = $('#bag-count');
const cartEmpty = $('#cart-empty');
const cartFooter = $('#cart-footer');
const checkoutComplete = $('#checkout-complete');
let activeProduct = null;
let activeSize = null;
let cart = readCart();
let statusTimeout;

$$('[data-inline-image]').forEach((image) => {
  image.src = media[image.dataset.inlineImage];
  if (image.dataset.inlineImage === 'hero') image.fetchPriority = 'high';
});

function readCart() {
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || '[]');
    if (!Array.isArray(saved)) return [];
    return saved.filter((line) => products[line.id] && waistSizes.includes(line.size) && Number.isInteger(line.qty) && line.qty > 0);
  } catch {
    return [];
  }
}
function saveCart() {
  try { localStorage.setItem(storageKey, JSON.stringify(cart)); } catch { /* Private browsing can disable storage. */ }
  renderCart();
}
function say(message) {
  const status = $('#status-message');
  status.textContent = message;
  status.classList.add('is-visible');
  clearTimeout(statusTimeout);
  statusTimeout = setTimeout(() => status.classList.remove('is-visible'), 2100);
}
function countItems() { return cart.reduce((total, line) => total + line.qty, 0); }
function renderCart() {
  const totalCount = countItems();
  bagCount.textContent = String(totalCount);
  bagCount.setAttribute('aria-label', `${totalCount} ${totalCount === 1 ? 'item' : 'items'} in bag`);
  cartItems.replaceChildren();
  cartEmpty.hidden = totalCount > 0;
  cartFooter.hidden = totalCount === 0;
  checkoutComplete.hidden = true;
  for (const line of cart) {
    const product = products[line.id];
    const row = document.createElement('article');
    row.className = 'cart-line';
    row.innerHTML = `<img class="cart-thumb" src="${product.image}" alt="" width="78" height="96"><div><h3>${product.name}</h3><p>${product.color} · Waist ${line.size}</p><div class="quantity-row"><button type="button" aria-label="Decrease quantity of ${product.name}" data-quantity="-1" data-id="${line.id}" data-size="${line.size}">−</button><span>${line.qty}</span><button type="button" aria-label="Increase quantity of ${product.name}" data-quantity="1" data-id="${line.id}" data-size="${line.size}">+</button></div><button type="button" class="remove-line" data-remove="${line.id}" data-size="${line.size}">Remove</button></div><span class="cart-line-price">${money(product.price * line.qty)}</span>`;
    cartItems.append(row);
  }
  const subtotal = cart.reduce((total, line) => total + products[line.id].price * line.qty, 0);
  cartSubtotal.textContent = money(subtotal);
}
function openProduct(id) {
  const product = products[id];
  if (!product) return;
  activeProduct = id;
  activeSize = null;
  $('#detail-image').src = product.image;
  $('#detail-image').alt = `${product.name} — ${product.color}`;
  $('#detail-fit').textContent = product.fit;
  $('#dialog-product-title').textContent = product.name;
  $('#detail-price').textContent = money(product.price);
  $('#detail-description').textContent = product.description;
  const options = $('#size-options');
  options.replaceChildren();
  waistSizes.forEach((size) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'size-button';
    button.textContent = size;
    button.setAttribute('aria-pressed', 'false');
    button.setAttribute('aria-label', `Waist size ${size}`);
    button.addEventListener('click', () => {
      activeSize = size;
      $$('.size-button', options).forEach((option) => option.setAttribute('aria-pressed', String(option === button)));
    });
    options.append(button);
  });
  productDialog.showModal();
}
function addToCart(id, size, openBag = true) {
  if (!products[id] || !waistSizes.includes(size)) return;
  const existing = cart.find((line) => line.id === id && line.size === size);
  if (existing) existing.qty += 1;
  else cart.push({ id, size, qty: 1 });
  saveCart();
  say(`${products[id].name} · ${size} added to your bag`);
  if (openBag) cartDialog.showModal();
}
function closeDialog(dialog) { if (dialog?.open) dialog.close(); }

$$('[data-product]').forEach((button) => button.addEventListener('click', () => openProduct(button.dataset.product)));
$$('[data-quick-add]').forEach((button) => button.addEventListener('click', () => openProduct(button.dataset.quickAdd)));
$('#detail-add').addEventListener('click', () => {
  if (!activeSize) { say('Choose a waist size first.'); $('#size-options button')?.focus(); return; }
  const productId = activeProduct;
  const size = activeSize;
  closeDialog(productDialog);
  addToCart(productId, size);
});
$('#open-cart').addEventListener('click', () => { renderCart(); cartDialog.showModal(); });
$$('[data-close-dialog]').forEach((button) => button.addEventListener('click', () => {
  closeDialog(productDialog);
  closeDialog(cartDialog);
}));
[productDialog, cartDialog].forEach((dialog) => dialog.addEventListener('click', (event) => {
  if (event.target === dialog) dialog.close();
}));
cartItems.addEventListener('click', (event) => {
  const button = event.target.closest('button');
  if (!button) return;
  const lineIndex = cart.findIndex((line) => line.id === button.dataset.id && line.size === button.dataset.size);
  if (lineIndex < 0) return;
  if (button.hasAttribute('data-remove')) cart.splice(lineIndex, 1);
  else if (button.hasAttribute('data-quantity')) {
    cart[lineIndex].qty += Number(button.dataset.quantity);
    if (cart[lineIndex].qty <= 0) cart.splice(lineIndex, 1);
  }
  saveCart();
});
$('#checkout-button').addEventListener('click', () => {
  if (cart.length === 0) return;
  cartFooter.hidden = true;
  cartEmpty.hidden = true;
  cartItems.replaceChildren();
  checkoutComplete.hidden = false;
});
$('#finish-demo').addEventListener('click', () => {
  cart = [];
  saveCart();
  closeDialog(cartDialog);
  document.querySelector('#shop').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
});

let currentFilter = 'all';
let currentSort = 'featured';
function updateCollection() {
  const grid = $('#product-grid');
  const cards = $$('.product-card', grid);
  cards.sort((a, b) => {
    if (currentSort === 'low-high') return Number(a.dataset.price) - Number(b.dataset.price) || Number(a.dataset.index) - Number(b.dataset.index);
    if (currentSort === 'high-low') return Number(b.dataset.price) - Number(a.dataset.price) || Number(a.dataset.index) - Number(b.dataset.index);
    return Number(a.dataset.index) - Number(b.dataset.index);
  });
  cards.forEach((card) => {
    const visible = currentFilter === 'all' || card.dataset.fit === currentFilter;
    card.hidden = !visible;
    grid.append(card);
  });
  const count = cards.filter((card) => !card.hidden).length;
  $('#result-count').textContent = `Showing ${count} ${count === 1 ? 'fit' : 'fits'}`;
  $('#empty-state').hidden = count !== 0;
}
$$('[data-filter]').forEach((button) => button.addEventListener('click', () => {
  currentFilter = button.dataset.filter;
  $$('[data-filter]').forEach((filter) => {
    const active = filter === button;
    filter.classList.toggle('is-active', active);
    filter.setAttribute('aria-pressed', String(active));
  });
  updateCollection();
}));
$('#sort-products').addEventListener('change', (event) => { currentSort = event.target.value; updateCollection(); });

const menuToggle = $('.menu-toggle');
const primaryNav = $('#primary-nav');
menuToggle.addEventListener('click', () => {
  const opened = menuToggle.getAttribute('aria-expanded') !== 'true';
  menuToggle.setAttribute('aria-expanded', String(opened));
  primaryNav.classList.toggle('is-open', opened);
});
primaryNav.addEventListener('click', (event) => {
  if (event.target.closest('a')) {
    menuToggle.setAttribute('aria-expanded', 'false');
    primaryNav.classList.remove('is-open');
  }
});
$('#year').textContent = new Date().getFullYear();
renderCart();

  </script>
</body>
</html>
